interface ValidationResult {
  valid: boolean;
  error?: string;
}

function validateCardNumber(cardNumber: string): ValidationResult {
  if (cardNumber.length !== 16) {
    return { valid: false, error: 'Card number must be 16 digits' };
  }
  return { valid: true };
}

function validateCVV(cvv: string): ValidationResult {
  if (cvv.length !== 3 && cvv.length !== 4) {
    return { valid: false, error: 'CVV must be 3 or 4 digits' };
  }
  return { valid: true };
}

function validateExpiryDate(expiryDate: string): ValidationResult {
  const expiryRegex = /^(0[1-9]|1[0-2])\/\d{2}$/;
  if (!expiryRegex.test(expiryDate)) {
    return { valid: false, error: 'Expiry date must be MM/YY format' };
  }

  const [month, year] = expiryDate.split('/');
  const expiryDateObj = new Date(2000 + parseInt(year), parseInt(month) - 1);

  if (expiryDateObj < new Date()) {
    return { valid: false, error: 'Card has expired' };
  }

  return { valid: true };
}

function validatePaymentDetails(payment: PaymentDetails): ValidationResult {
  const checks = [
    validateCardNumber(payment.cardNumber),
    validateCVV(payment.cvv),
    validateExpiryDate(payment.expiryDate)
  ];

  const failure = checks.find(result => !result.valid);
  return failure ?? { valid: true };
}

