interface SubscriptionRepository {
  getByUserId(userId: string): Promise<Subscription | null>;
  upsert(subscription: SubscriptionUpdate): Promise<void>;
}

class PostgresSubscriptionRepository implements SubscriptionRepository {
  constructor(private db: Database) {}

  async getByUserId(userId: string): Promise<Subscription | null> {
    const query = 'SELECT * FROM subscriptions WHERE user_id = $1';
    const rows = await this.db.query(query, [userId]);

    if (rows.length === 0) {
      return null;
    }

    return this.mapRowToSubscription(rows[0]);
  }

  async upsert(subscription: SubscriptionUpdate): Promise<void> {
    const query = `
      INSERT INTO subscriptions (user_id, tier, valid_until, features) 
      VALUES ($1, $2, $3, $4) 
      ON CONFLICT (user_id) 
      DO UPDATE SET tier = $2, valid_until = $3, features = $4
    `;

    await this.db.query(query, [
      subscription.userId,
      subscription.tier,
      subscription.validUntil,
      JSON.stringify(subscription.features)
    ]);
  }

  private mapRowToSubscription(row: any): Subscription {
    return {
      userId: row.user_id,
      tier: row.tier,
      validUntil: new Date(row.valid_until),
      features: JSON.parse(row.features)
    };
  }
}

// Business logic now uses repository
async function upgradeUserSubscription(
  repo: SubscriptionRepository,
  userId: string,
  tier: PaidTier
): Promise<void> {
  const features = TIER_CONFIGS[tier].features;
  const validUntil = calculateValidUntil(1);

  await repo.upsert({ userId, tier, validUntil, features });
}
